class Solution {
public:
    int findShortestCycle(int n, std::vector<std::vector<int>>& edges) {
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        int ans = INT_MAX;
        for (int start = 0; start < n; ++start) {
            std::vector<int> dist(n, -1);
            std::vector<int> parent(n, -1);
            dist[start] = 0;
            std::queue<int> q;
            q.push(start);
            while (!q.empty()) {
                int u = q.front();
                q.pop();
                for (int v : adj[u]) {
                    if (dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        parent[v] = u;
                        q.push(v);
                    } else if (parent[u] != v) {
                        ans = std::min(ans, dist[u] + dist[v] + 1);
                    }
                }
            }
        }
        return ans == INT_MAX ? -1 : ans;
    }
};

class Solution {
    public int findShortestCycle(int n, int[][] edges) {
        java.util.List<Integer>[] adj = new java.util.ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new java.util.ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        int ans = Integer.MAX_VALUE;
        for (int start = 0; start < n; start++) {
            int[] dist = new int[n];
            int[] parent = new int[n];
            java.util.Arrays.fill(dist, -1);
            java.util.Arrays.fill(parent, -1);
            dist[start] = 0;
            java.util.Queue<Integer> q = new java.util.LinkedList<>();
            q.offer(start);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int v : adj[u]) {
                    if (dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        parent[v] = u;
                        q.offer(v);
                    } else if (parent[u] != v) {
                        ans = Math.min(ans, dist[u] + dist[v] + 1);
                    }
                }
            }
        }
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }
}

var findShortestCycle = function(n, edges) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    let ans = Infinity;
    for (let start = 0; start < n; start++) {
        const dist = new Int32Array(n).fill(-1);
        const parent = new Int32Array(n).fill(-1);
        dist[start] = 0;
        const q = [start];
        let head = 0;
        while (head < q.length) {
            const u = q[head++];
            for (const v of adj[u]) {
                if (dist[v] === -1) {
                    dist[v] = dist[u] + 1;
                    parent[v] = u;
                    q.push(v);
                } else if (parent[u] !== v) {
                    ans = Math.min(ans, dist[u] + dist[v] + 1);
                }
            }
        }
    }
    return ans === Infinity ? -1 : ans;
};
